const D = { density:.5, scale:1, energy:.55, speed:1, hue:210, x:.5, y:.5, fold:.5, grain:.5, style:'ink', act:'grow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const ink=style==='ink', blue=style==='blueprint', neon=style==='neon', thermal=style==='thermal';
const en=clp(P.energy,0,1)*(.55+.55*K.intensity);
const target=Math.round(lrp(70,240,clp(P.density,0,1)));
const Rmax=u*0.40;

// t0 / beat reset guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// ---- static ground buffer (paper / dark) ----
const bkey=W+'x'+Hh+':'+style+':'+P.seed+':'+Math.round(P.grain*4);
if(!S.bg||S.bgKey!==bkey){
  S.bgKey=bkey;
  const g=createGraphics(W,Hh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  if(ink){
    g.fill(41,11,82); g.rect(0,0,W,Hh);
    for(let i=0;i<150;i++){const bx=fr(i*4+1)*W,by=fr(i*4+2)*Hh,rr=u*(0.05+fr(i*4+3)*0.20);
      g.fill(fr(i*4+5)<.5?41:33, 9, fr(i*4+4)<.5?74:88, 5); g.ellipse(bx,by,rr,rr);}
    const gn=Math.round(2600*(0.4+P.grain));
    for(let i=0;i<gn;i++){g.fill(34,14,fr(i*3+50)<.5?55:100, 5); g.rect(fr(i*3+51)*W,fr(i*3+52)*Hh,1.6,1.6);}
  } else if(blue){
    g.fill(214,72,19); g.rect(0,0,W,Hh);
    g.stroke(200,42,78,22); g.strokeWeight(1);
    for(let x=0;x<=W;x+=u*0.06)g.line(x,0,x,Hh);
    for(let y=0;y<=Hh;y+=u*0.06)g.line(0,y,W,y);
    g.noStroke();
    g.fill(200,60,90,10);
    for(let i=0;i<40;i++)g.rect(fr(i*5+9)*W,fr(i*5+10)*Hh,u*0.01,u*0.01);
  } else { // neon / thermal dark
    g.fill(thermal?232:252,55,7); g.rect(0,0,W,Hh);
    for(let i=0;i<64;i++){const f=i/63;g.fill(thermal?250:225,40,lrp(3,11,f),9);
      g.ellipse(W*0.5,Hh*0.52,u*(2.1-f*1.7),u*(2.1-f*1.7));}
  }
  S.bg=g;
}

// ---- init / reset curve ----
function initCurve(){
  const n0=Math.max(16, Math.round(target*0.20));
  const arr=[]; const r0=u*0.11;
  for(let i=0;i<n0;i++){const a=i/n0*6.2832; const rr=r0*(0.82+fr(i*9+3)*0.36);
    arr.push({x:Math.cos(a)*rr, y:Math.sin(a)*rr});}
  S.nodes=arr;
}
const period=34;
const epochNow=Math.floor(K.t/period);
if(!S.nodes || S.seedUsed!==P.seed || S.epochN!==epochNow){
  S.seedUsed=P.seed; S.epochN=epochNow; initCurve();
}

// ---- differential growth step ----
const spacing=u*0.030*lrp(1.45,0.68,clp(P.fold,0,1));
const r=spacing, maxLen=spacing*1.75;
const attrAmt=0.16, repAmt=spacing*0.42;
let growRate=P.speed;
if(P.act==='pulse') growRate*=(0.5+1.4*K.intensity);
const subs=clp(Math.round(1+growRate*0.7),1,3);

function stepSim(){
  const N=S.nodes; const n=N.length; if(n<3)return;
  const cs=r; const grid=new Map();
  for(let i=0;i<n;i++){const p=N[i];const k=Math.floor(p.x/cs)+','+Math.floor(p.y/cs);
    let b=grid.get(k); if(!b){b=[];grid.set(k,b);} b.push(i);}
  const rx=new Float64Array(n), ry=new Float64Array(n);
  for(let i=0;i<n;i++){
    const p=N[i];const cx=Math.floor(p.x/cs),cy=Math.floor(p.y/cs);
    for(let ox=-1;ox<=1;ox++)for(let oy=-1;oy<=1;oy++){
      const b=grid.get((cx+ox)+','+(cy+oy)); if(!b)continue;
      for(let jj=0;jj<b.length;jj++){const j=b[jj]; if(j===i)continue; const q=N[j];
        let dx=p.x-q.x,dy=p.y-q.y; const d2=dx*dx+dy*dy; if(d2>r*r||d2<1e-5)continue;
        const d=Math.sqrt(d2); const w=(r-d)/r; rx[i]+=dx/d*w; ry[i]+=dy/d*w;}
    }
  }
  for(let i=0;i<n;i++){
    const p=N[i]; const a=N[(i-1+n)%n], c=N[(i+1)%n];
    const mx=(a.x+c.x)*0.5-p.x, my=(a.y+c.y)*0.5-p.y;
    p.x+=clp(rx[i],-2.5,2.5)*repAmt + mx*attrAmt;
    p.y+=clp(ry[i],-2.5,2.5)*repAmt + my*attrAmt;
    const dd=Math.sqrt(p.x*p.x+p.y*p.y); if(dd>Rmax){p.x*=Rmax/dd;p.y*=Rmax/dd;}
  }
  if(n<target){
    const out=[];
    for(let i=0;i<n;i++){out.push(N[i]);const q=N[(i+1)%n];
      const dx=q.x-N[i].x,dy=q.y-N[i].y;
      if(dx*dx+dy*dy>maxLen*maxLen && out.length<target)out.push({x:N[i].x+dx*0.5,y:N[i].y+dy*0.5});}
    S.nodes=out;
  }
}
for(let s=0;s<subs;s++)stepSim();

// ---- render ----
image(S.bg,0,0,W,Hh);
const N=S.nodes; const n=N.length;
push();
// continuous orbit + rotation drift => every edge pixel shifts over 8s (motion floor)
translate(P.x*W + Math.sin(K.t*0.11)*u*0.035, P.y*Hh + Math.cos(K.t*0.083)*u*0.035);
scale(clp(P.scale,0.4,2)*(1+K.swell*0.02*en+A.rms*0.05));
rotate(Math.sin(K.t*0.05)*0.10 + K.t*0.006);
noFill();
const lw=u*0.0055*(0.7+en*0.8+A.bass*0.6);

function drawCurve(off){
  beginShape();
  curveVertex(N[n-1].x+off,N[n-1].y+off);
  for(let i=0;i<n;i++)curveVertex(N[i].x+off,N[i].y+off);
  curveVertex(N[0].x+off,N[0].y+off);
  curveVertex(N[1].x+off,N[1].y+off);
  endShape();
}

if(neon){
  blendMode(ADD);
  drawingContext.shadowBlur=16; drawingContext.shadowColor='hsl('+Math.round(H)+',90%,60%)';
  stroke(H,78,100,72); strokeWeight(lw); drawCurve(0);
  drawingContext.shadowBlur=0;
  stroke(md(H+30,360),50,100,50); strokeWeight(lw*0.4); drawCurve(0);
  blendMode(BLEND);
} else if(blue){
  stroke(198,26,98,88); strokeWeight(lw*0.8); drawCurve(0);
  stroke(198,40,100,30);
  for(let i=0;i<n;i+=5){const t=u*0.006; line(N[i].x-t,N[i].y,N[i].x+t,N[i].y); line(N[i].x,N[i].y-t,N[i].x,N[i].y+t);}
} else if(thermal){
  strokeWeight(lw*1.1);
  for(let i=0;i<n;i++){const p=N[i],q=N[(i+1)%n];
    const rad=Math.sqrt(p.x*p.x+p.y*p.y)/Rmax;
    const heat=clp(rad+0.16*Math.sin(K.t*1.1+i*0.4)+A.mid*0.3,0,1);
    const hh=lrp(232,0,heat); const bb=lrp(55,100,heat);
    stroke(hh,lrp(90,70,heat),bb, 82);
    line(p.x,p.y,q.x,q.y);}
} else { // ink
  drawingContext.shadowBlur=7*en; drawingContext.shadowColor='rgba(26,20,12,0.5)';
  stroke(28,32,17,92); strokeWeight(lw); drawCurve(0);
  drawingContext.shadowBlur=0;
  stroke(30,18,34,38); strokeWeight(lw*0.42); drawCurve(-lw*0.5);
}
pop();

// treble sparkle nodes (audio on top, real-time)
if(A.treble>0.05){
  push();
  translate(P.x*W + Math.sin(K.t*0.11)*u*0.035, P.y*Hh + Math.cos(K.t*0.083)*u*0.035);
  scale(clp(P.scale,0.4,2)); rotate(Math.sin(K.t*0.05)*0.10 + K.t*0.006);
  blendMode(ADD); noStroke();
  for(let i=0;i<n;i+=7){const p=N[i]; fill(neon?H:46,40,100,A.treble*60); ellipse(p.x,p.y,u*0.006,u*0.006);}
  blendMode(BLEND); pop();
}
blendMode(BLEND);
